import React, { useEffect, useRef } from "react";
import { motion } from "framer-motion";
import { ArrowDown, Thermometer, Microscope } from "lucide-react";
import Button from "../ui/Button";

const container = {
  hidden: {},
  visible: { transition: { staggerChildren: 0.12, delayChildren: 0.3 } },
};

const item = {
  hidden: { opacity: 0, y: 28 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.7, ease: [0.25, 0.46, 0.45, 0.94] },
  },
};

export default function Hero() {
  const canvasRef = useRef(null);

  // Particle canvas
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext("2d");
    let animId;
    let w = (canvas.width = canvas.offsetWidth);
    let h = (canvas.height = canvas.offsetHeight);

    const particles = Array.from({ length: 40 }, () => ({
      x: Math.random() * w,
      y: Math.random() * h,
      r: Math.random() * 1.5 + 0.5,
      dx: (Math.random() - 0.5) * 0.3,
      dy: (Math.random() - 0.5) * 0.3,
      a: Math.random() * 0.4 + 0.05,
    }));

    const draw = () => {
      ctx.clearRect(0, 0, w, h);

      particles.forEach((p) => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(255,255,255,${p.a})`;
        ctx.fill();

        p.x += p.dx;
        p.y += p.dy;

        if (p.x < 0 || p.x > w) p.dx *= -1;
        if (p.y < 0 || p.y > h) p.dy *= -1;
      });

      animId = requestAnimationFrame(draw);
    };

    draw();

    const handleResize = () => {
      w = canvas.width = canvas.offsetWidth;
      h = canvas.height = canvas.offsetHeight;
    };

    window.addEventListener("resize", handleResize);

    return () => {
      cancelAnimationFrame(animId);
      window.removeEventListener("resize", handleResize);
    };
  }, []);

  const scrollDown = () => {
    document
      .getElementById("cold-chain")
      ?.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <section className="relative min-h-screen flex overflow-hidden bg-charcoal-950">
      {/* Background */}
      <div className="absolute inset-0 bg-gradient-to-br from-blue-950 via-charcoal-950 to-charcoal-950" />
      <div className="absolute inset-0 grid-pattern opacity-100 pointer-events-none" />

      <div className="absolute top-[-15%] right-[20%] w-[600px] h-[600px] rounded-full bg-blue-800/10 blur-[100px]" />
      <div className="absolute bottom-[-10%] left-[10%] w-[400px] h-[400px] rounded-full bg-blue-700/8 blur-[80px]" />

      {/* Particles */}
      <canvas
        ref={canvasRef}
        className="absolute inset-0 w-full h-full pointer-events-none"
        style={{ opacity: 0.6 }}
      />

      {/* Content */}
      <div className="relative z-10 max-w-7xl mx-auto px-6 lg:px-10 flex flex-col lg:flex-row items-center min-h-screen py-28 lg:py-0 gap-16">
        {/* LEFT */}
        <motion.div
          variants={container}
          initial="hidden"
          animate="visible"
          className="flex-1 max-w-2xl"
        >
          <motion.h1
            variants={item}
            className="font-display text-[clamp(2.8rem,6vw,5rem)] text-white leading-[1.05] mb-7"
          >
            Cold Chain &{" "}
            <em className="text-blue-400 not-italic">Pathology</em>
            <br />
            Infrastructure
            <br />
            <span className="text-white/40 text-[clamp(2rem,4vw,3.5rem)]">
              That Performs.
            </span>
          </motion.h1>

          <motion.p
            variants={item}
            className="text-white/55 text-[1.05rem] leading-[1.85] mb-10 max-w-lg"
          >
            A focused showcase of Baylem's advanced cold chain storage systems,
            histopathology laboratories, and mortuary infrastructure delivered
            across all 47 counties of Kenya.
          </motion.p>

          <motion.div variants={item} className="flex flex-wrap gap-4">
            <Button
              variant="primary"
              onClick={() =>
                document
                  .getElementById("cold-chain")
                  ?.scrollIntoView({ behavior: "smooth" })
              }
              icon={<Thermometer size={15} />}
            >
              Cold Chain Solutions
            </Button>

            <Button
              variant="ghost"
              onClick={() =>
                document
                  .getElementById("pathology")
                  ?.scrollIntoView({ behavior: "smooth" })
              }
              icon={<Microscope size={15} />}
            >
              Pathology & Mortuary Systems
            </Button>
          </motion.div>
        </motion.div>

        {/* RIGHT (FIXED - REMOVED BROKEN JSX) */}
        <motion.div className="flex-1">
          <img
            src={require("../../assets/images/hero/baylem-hero.jpeg")}
            alt="Baylem cold chain installation"
            className="w-full h-[460px] object-cover rounded-2xl"
          />
        </motion.div>
      </div>

      {/* Scroll button */}
      <motion.button
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 1.8, duration: 0.6 }}
        onClick={scrollDown}
        className="absolute bottom-8 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2 text-white/30 hover:text-white/60 transition-colors"
      >
        <span className="text-[10px] tracking-[0.2em] uppercase font-semibold">
          Scroll
        </span>
        <motion.div
          animate={{ y: [0, 5, 0] }}
          transition={{ repeat: Infinity, duration: 1.6 }}
        >
          <ArrowDown size={16} />
        </motion.div>
      </motion.button>
    </section>
  );
}
